package com.bank.streak.service;

import com.bank.streak.model.Order;
import com.bank.streak.repository.OrderRepository;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.*;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class StreakService {
    private static final Logger log = Logger.getLogger(StreakService.class.getName());
    private final OrderRepository repo;
    public StreakService(OrderRepository repo) { this.repo = repo; }

    public List<String> customersWithConsecutiveDays() {
        // Stage 1: distinct (customer, day) — multiple same-day orders count once.
        Map<String, TreeSet<LocalDate>> daysByCustomer = new TreeMap<>();
        for (Order o : repo.findAll()) {
            daysByCustomer.computeIfAbsent(o.getCustomerId(), k -> new TreeSet<>()).add(o.getOrderDay());
        }
        List<String> qualifying = new ArrayList<>();
        for (Map.Entry<String, TreeSet<LocalDate>> e : daysByCustomer.entrySet()) {
            // Stage 2 + 3: walk sorted days, compare each to the previous (LAG).
            LocalDate prev = null;
            boolean hasStreak = false;
            for (LocalDate d : e.getValue()) {               // ORDER BY d
                if (prev != null && ChronoUnit.DAYS.between(prev, d) == 1) { // d - prev_d = 1
                    hasStreak = true;
                    break;
                }
                prev = d;                                     // LAG moves forward
            }
            if (hasStreak) qualifying.add(e.getKey());
        }
        qualifying = qualifying.stream().distinct().collect(Collectors.toList());
        log.info(() -> "Customers with a consecutive-day streak: " + qualifying);
        return qualifying;
    }
}
